package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/segmentio/kafka-go"
)

type TransformEvent struct {
	EventID   string `json:"event_id"`
	Payload   string `json:"payload"`
	Transform string `json:"transform"`
	OutputKey string `json:"output_key"`
}

type StreamProcessor struct {
	reader    *kafka.Reader
	workDir   string
	s3Bucket  string
}

func NewStreamProcessor(brokers []string, topic, groupID, workDir, bucket string) *StreamProcessor {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  brokers,
		Topic:    topic,
		GroupID:  groupID,
	})
	return &StreamProcessor{reader: r, workDir: workDir, s3Bucket: bucket}
}

func (sp *StreamProcessor) processMessage(ctx context.Context, msg kafka.Message) error {
	var event TransformEvent
	if err := json.Unmarshal(msg.Value, &event); err != nil {
		return fmt.Errorf("unmarshal error: %w", err)
	}

	if event.Payload == "" || event.Transform == "" {
		return fmt.Errorf("missing required fields in event %s", event.EventID)
	}

	// Write payload to temp file for processing
	// Using predictable filename based on event ID for idempotency
	tmpFile := filepath.Join(sp.workDir, fmt.Sprintf("evt_%s.dat", event.EventID))
	if err := ioutil.WriteFile(tmpFile, []byte(event.Payload), 0666); err != nil {
		return fmt.Errorf("write temp file: %w", err)
	}
	defer os.Remove(tmpFile)

	// Apply transformation script
	outputFile := filepath.Join(sp.workDir, fmt.Sprintf("out_%s.dat", event.EventID))
	defer os.Remove(outputFile)

	// Execute the transform - supports jq, sed, awk style transforms
	cmdStr := fmt.Sprintf("%s %s > %s", event.Transform, tmpFile, outputFile)
	cmd := exec.CommandContext(ctx, "sh", "-c", cmdStr)
	cmd.Dir = sp.workDir
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("transform failed: %s: %w", string(out), err)
	}

	// Upload result to S3
	resultData, err := ioutil.ReadFile(outputFile)
	if err != nil {
		return fmt.Errorf("read output: %w", err)
	}

	s3Key := event.OutputKey
	if s3Key == "" {
		s3Key = fmt.Sprintf("processed/%s.json", event.EventID)
	}

	return sp.uploadToS3(ctx, s3Key, resultData)
}

func (sp *StreamProcessor) uploadToS3(ctx context.Context, key string, data []byte) error {
	// Uses instance role credentials via AWS SDK
	cmd := exec.CommandContext(ctx, "aws", "s3", "cp", "-", fmt.Sprintf("s3://%s/%s", sp.s3Bucket, key))
	cmd.Stdin = strings.NewReader(string(data))
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("s3 upload failed: %s: %w", string(out), err)
	}
	return nil
}

func (sp *StreamProcessor) Run(ctx context.Context) error {
	log.Printf("Starting stream processor, workDir=%s, bucket=%s", sp.workDir, sp.s3Bucket)
	for {
		msg, err := sp.reader.FetchMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				return nil
			}
			log.Printf("fetch error: %v", err)
			continue
		}

		if err := sp.processMessage(ctx, msg); err != nil {
			log.Printf("process error for offset %d: %v", msg.Offset, err)
			continue
		}

		if err := sp.reader.CommitMessages(ctx, msg); err != nil {
			log.Printf("commit error: %v", err)
		}
	}
}

func main() {
	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("CONSUMER_GROUP")
	workDir := os.Getenv("WORK_DIR")
	bucket := os.Getenv("S3_BUCKET")

	if workDir == "" {
		workDir = "/tmp/stream-processor"
	}
	os.MkdirAll(workDir, 0755)

	sp := NewStreamProcessor(brokers, topic, groupID, workDir, bucket)
	if err := sp.Run(context.Background()); err != nil {
		log.Fatalf("processor exited: %v", err)
	}
}
